    faq1Q: "Why is male reproductive health evaluated on a 72–90 day cycle?",
    faq1A: "Human spermatogenesis from initial stem spermatogonia to mature ejaculated spermatozoa takes approximately 64 to 74 days, followed by 10 to 14 days of epididymal transit. Modifiable interventions—such as eliminating laptop heat, taking CoQ10/Zinc, and improving sleep—require a full spermatogenic cycle before their cellular benefits can be measured in semen parameters.",
    faq2Q: "What are the WHO 6th Edition reference standards used by Reprogenix AI?",
    faq2A: "The World Health Organization (WHO) Semen Analysis Manual 6th Edition (2021) establishes the lower 5th percentile reference distribution from fertile men: Semen Concentration ≥ 16 million/mL, Progressive Motility ≥ 30%, Total Motility ≥ 42%, and Strict Normal Morphology ≥ 4.0%. Reprogenix AI benchmarks all patient records against these international thresholds.",
    faq3Q: "How does Reprogenix AI protect sensitive reproductive health data?",
    faq3A: "We enforce a Zero Persistent PII architecture. Digital screenings and lifestyle assessments are calculated in ephemeral volatile memory (RAM) and immediately discarded upon session termination. No identifying names or medical numbers are stored in cloud database records, satisfying HIPAA and GDPR Article 9 requirements.",
    faq4Q: "How does the 5-Tier Safe Triage decision engine ensure patient safety?",
    faq4A: "Our safety engine is designed to distinguish screening from medical diagnosis. Acute symptoms (sudden unilateral testicular pain, trauma, or suspected torsion) trigger Tier 0 Emergency and immediately bypass all algorithmic scoring, directing the user to the nearest Emergency Room. Severe clinical conditions (palpable varicocele, azoospermia) route to Tier 1 Specialist Andrology, while modifiable factors route to Tiers 2–4.",
    faq5Q: "How do tele-andrology video and audio consultations work?",
    faq5A: "Patients can connect directly with board-certified andrologists (such as Dr. Sarah Johnson) through end-to-end encrypted WebRTC video rooms, direct clinical voice calls, or verified WhatsApp messaging lines for follow-up review and repeat lab scheduling.",
    faq6Q: "What are faith-conscious and non-invasive semen collection options?",
    faq6A: "Reprogenix AI supports religious and culturally sensitive pathways, including non-spermicidal perforated Silastic collection sheaths used during natural marital intercourse, ensuring andrological evaluations respect all spiritual and cultural values.",

