    faq1Q: "¿Por qué se evalúa la salud reproductiva en un ciclo de 72 a 90 días?",
    faq1A: "La espermatogénesis humana dura entre 64 y 74 días, más 10 a 14 días de tránsito por el epidídimo. Las mejoras como evitar el calor del portátil o tomar suplementos requieren un ciclo entero para reflejarse en los parámetros seminales.",
    faq2Q: "¿Cuáles son los valores de referencia de la OMS 6ª Edición aplicados?",
    faq2A: "El Manual de la OMS (2021) establece el percentil 5: Concentración ≥ 16 millones/mL, Motilidad Progresiva ≥ 30%, Motilidad Total ≥ 42% y Morfología Normal ≥ 4,0%. Reprogenix AI evalúa todos los casos con estos criterios.",
    faq3Q: "¿Cómo protege Reprogenix AI la privacidad de mis datos reproductivos?",
    faq3A: "Operamos con una arquitectura de Cero Almacenamiento Persistente. Sus datos se analizan en memoria RAM efímera y se borran al cerrar la sesión, cumpliendo con HIPAA y RGPD Artículo 9.",
    faq4Q: "¿Cómo garantiza la seguridad del paciente el motor de Triaje Seguro?",
    faq4A: "Distingue el cribado del diagnóstico médico. Los síntomas agudos activan el Nivel 0 de Emergencia y derivan de inmediato al hospital más cercano sin demoras.",
    faq5Q: "¿Cómo funcionan las videoconsultas y llamadas de teleandrología?",
    faq5A: "Los pacientes se conectan con andrólogos certificados en salas WebRTC con cifrado de extremo a extremo, llamadas directas o mensajería WhatsApp para seguimiento clínico.",
    faq6Q: "¿Qué opciones existen para recolección de muestras acorde a convicciones religiosas?",
    faq6A: "Admitimos el uso de preservativos silásticos no espermicidas perforados durante la intimidad conyugal natural, respetando plenamente los valores éticos y religiosos.",

