    privacyGuideDesc: "Procesamiento efímero en memoria RAM. Cero identificadores persistentes de pacientes o registros en base de datos.",
    tier0TitleFull: "Nivel 0: Alerta Clínica de Emergencia Aguda",
    tier0DescFull: "Alerta clínica de emergencia aguda: síntomas graves o traumatismo agudo detectado. Se requiere intervención especializada inmediata y evaluación en urgencias.",
    tier1TitleFull: "Nivel 1: Derivación a Especialista en Urología y Andrología",
    tier1DescFull: "Se requiere derivación a especialista. Los hallazgos sugieren patología clínicamente significativa (p. ej., varicocele palpable, oligozoospermia severa o alteración del eje endocrino). Se recomienda ecografía Doppler escrotal y evaluación hormonal en 2 semanas.",
    tier2TitleFull: "Nivel 2: Atención Primaria y Optimización del Estilo de Vida",
    tier2DescFull: "Intervenciones de atención primaria y optimización del estilo de vida recomendadas: reducir la exposición al calor escrotal, mejorar la higiene del sueño (≥7 h), adoptar nutrición rica en antioxidantes (CoQ10, Zinc, Selenio), aumentar el ejercicio moderado a 4-5 días/semana y programar un análisis de semen de seguimiento tras un ciclo completo de espermatogénesis de 72-90 días.",
    tier3TitleFull: "Nivel 3: Investigación de Subfertilidad Centrada en la Pareja",
    tier3DescFull: "Investigación de subfertilidad centrada en la pareja recomendada. Derivar a especialista en andrología para análisis avanzado de semen (fragmentación de ADN, ensayo de ROS), revisión del panel hormonal y evaluación paralela de la pareja.",
    tier4TitleFull: "Nivel 4: Autocuidado Preventivo y Monitoreo",
    tier4DescFull: "No se identificaron problemas clínicos inmediatos. Continúe con las prácticas preventivas de salud que incluyen nutrición equilibrada, actividad física regular, sueño adecuado (7-8 h) y revisiones anuales.",
  
