    faq1Q: "Pourquoi la fertilité masculine s'évalue-t-elle sur 72 à 90 jours ?",
    faq1A: "La spermatogenèse humaine nécessite 64 à 74 jours, suivis de 10 à 14 jours de transit dans l'épididyme. Les interventions modifiables requièrent ainsi un cycle biologique complet pour être visibles lors du spermogramme.",
    faq2Q: "Quels sont les seuils de référence de l'OMS 6e Édition retenus ?",
    faq2A: "Le manuel OMS (2021) fixe le 5e percentile : Concentration ≥ 16 M/mL, Mobilité progressive ≥ 30%, Mobilité totale ≥ 42% et Formes typiques ≥ 4%. Reprogenix AI applique ces critères internationaux.",
    faq3Q: "Comment Reprogenix AI protège-t-il la confidentialité médicale ?",
    faq3A: "Notre architecture ne conserve aucune donnée persistante. Toutes les évaluations s'exécutent en mémoire vive volatile (RAM) et sont détruites à la fermeture de la session, conformément à l'HIPAA et au RGPD Art. 9.",
    faq4Q: "Comment le moteur de triage sécurisé protège-t-il les patients ?",
    faq4A: "Il distingue formellement dépistage et diagnostic médical. Tout symptôme d'alerte active le Palier 0 d'Urgence et redirige le patient vers les Urgences hospitalières sans délai.",
    faq5Q: "Comment se déroulent les consultations en télé-andrologie ?",
    faq5A: "Les patients échangent en visioconférence chiffrée de bout en bout WebRTC, par appel vocal ou via WhatsApp professionnel avec nos andrologues référents.",
    faq6Q: "Quelles sont les modalités de recueil compatibles avec les convictions personnelles ?",
    faq6A: "Nous proposons l'usage d'étuis en silicone perforés non spermicides utilisés lors de rapports conjugaux naturels, dans le respect absolu de toutes les sensibilités.",

