    tier0TitleFull: "Niveau 0 : Alerte Clinique d'Urgence Aiguë",
    tier0DescFull: "Alerte d'urgence clinique aiguë : symptômes graves ou traumatisme aigu détectés. Intervention spécialisée immédiate et évaluation aux urgences requises.",
    tier1TitleFull: "Niveau 1 : Orientation vers un Spécialiste en Urologie et Andrologie",
    tier1DescFull: "Orientation vers un spécialiste requise. Les résultats suggèrent une pathologie cliniquement significative (ex. varicocèle palpable, oligozoospermie sévère). Échographie Doppler scrotale et bilan hormonal recommandés sous 2 semaines.",
    tier2TitleFull: "Niveau 2 : Soins Primaires et Optimisation du Mode de Vie",
    tier2DescFull: "Interventions en soins primaires et optimisation du mode de vie recommandées : réduire l'exposition thermique scrotale, améliorer le sommeil (≥7 h), adopter une alimentation antioxydante (CoQ10, Zinc, Sélénium), pratiquer un exercice modéré 4-5 j/semaine et prévoir un spermogramme de contrôle après un cycle complet de 72-90 jours.",
    tier3TitleFull: "Niveau 3 : Bilan de Sous-Fertilité Centré sur le Couple",
    tier3DescFull: "Bilan de sous-fertilité centré sur le couple justifié. Orientation vers un andrologue pour analyse séminale approfondie (fragmentation de l'ADN, test ROS), bilan hormonal et évaluation conjointe de la partenaire.",
    tier4TitleFull: "Niveau 4 : Autonomie Préventive et Surveillance",
    tier4DescFull: "Aucune préoccupation clinique immédiate identifiée. Poursuivre les mesures préventives usuelles : alimentation équilibrée, activité physique régulière, sommeil suffisant (7-8 h) et contrôle annuel.",
  
