    faq1Q: "Warum wird die Zeugungsfähigkeit in einem 72–90 Tage Zyklus beurteilt?",
    faq1A: "Die Neubildung von Spermien dauert ca. 64 bis 74 Tage, gefolgt von 10 bis 14 Tagen Reifung im Nebenhoden. Positive Veränderungen (wie Hitzevermeidung oder Nährstoffe) zeigen sich erst nach einem vollen Zyklus im Spermiogramm.",
    faq2Q: "Welche WHO-Referenzwerte der 6. Auflage werden herangezogen?",
    faq2A: "Das WHO-Handbuch (2021) definiert das untere 5. Perzentil: Konzentration ≥ 16 Mio/mL, Progressivmotilität ≥ 30%, Gesamtmotilität ≥ 42% und Normalformen ≥ 4,0%. Reprogenix AI vergleicht alle Werte mit diesen Standards.",
    faq3Q: "Wie schützt Reprogenix AI meine sensiblen Gesundheitsdaten?",
    faq3A: "Wir nutzen eine Architektur ohne persistente Speicherung. Daten werden im flüchtigen Arbeitsspeicher (RAM) verarbeitet und mit Beendigung der Sitzung gelöscht, konform mit DSGVO Art. 9 und HIPAA.",
    faq4Q: "Wie stellt das 5-Stufen-Triagesystem die Patientensicherheit sicher?",
    faq4A: "Es trennt Screening von ärztlicher Diagnose. Akute Alarmsymptome leiten den Patienten ohne Verzögerung direkt an die nächstgelegene Notfallklinik weiter.",
    faq5Q: "Wie laufen die Videosprechstunden und Telefonate ab?",
    faq5A: "Patienten sprechen direkt über verschlüsselte WebRTC-Videoräume, Telefon oder verifizierten WhatsApp-Kanal mit erfahrenen Andrologen.",
    faq6Q: "Gibt es Optionen zur Probengewinnung bei religiösen Vorbehalten?",
    faq6A: "Wir unterstützen die Verwendung nicht-spermizider, perforierter Silikonkondome während des natürlichen ehelichen Verkehrs unter voller Achtung religiöser Werte.",

