    faq1Q: "पुरुष प्रजनन क्षमता का मूल्यांकन 72 से 90 दिनों के चक्र में क्यों किया जाता है?",
    faq1A: "शुक्राणु बनने में 64 से 74 दिन और एपिडीडिमिस में परिपक्व होने में 10 से 14 दिन लगते हैं। जीवनशैली में किए गए सुधारों का असर वीर्य रिपोर्ट में दिखने के लिए एक पूरा चक्र आवश्यक होता है।",
    faq2Q: "Reprogenix AI द्वारा प्रयुक्त WHO 6ठे संस्करण के मानक क्या हैं?",
    faq2A: "WHO मैन्युअल (2021) का 5वां पर्सेंटाइल: सांद्रता ≥ 16 मिलियन/mL, प्रोग्रेसिव गतिशीलता ≥ 30%, कुल गतिशीलता ≥ 42% और सामान्य आकृति ≥ 4%। हमारा सिस्टम इसी पर आधारित है।",
    faq3Q: "Reprogenix AI मेरी निजी स्वास्थ्य जानकारी को कैसे सुरक्षित रखता है?",
    faq3A: "हम जीरो परसिस्टेंट डेटा नीति अपनाते हैं। डेटा केवल रैम में प्रोसेस होकर तुरंत नष्ट हो जाता है; क्लाउड में कोई नाम या मेडिकल नंबर स्टोर नहीं होता (HIPAA एवं GDPR अनुरूप)।",
    faq4Q: "5-स्तरीय सुरक्षित ट्राइएज मरीज़ की सुरक्षा कैसे सुनिश्चित करता है?",
    faq4A: "यह स्क्रीनिंग और डॉक्टर के निदान में स्पष्ट भेद करता है। आपातकालीन लक्षणों को तुरंत स्तर 0 पर अस्पताल की इमरजेंसी के लिए निर्देशित किया जाता है।",
    faq5Q: "टेली-एंड्रोलॉजी वीडियो और ऑडियो परामर्श कैसे काम करते हैं?",
    faq5A: "मरीज़ सीधे एनक्रिप्टेड WebRTC वीडियो, डायरेक्ट फोन कॉल या सत्यापित व्हाट्सएप के जरिए वरिष्ठ एंड्रोलॉजिस्ट से जुड़ सकते हैं।",
    faq6Q: "धार्मिक और सांस्कृतिक मान्यताओं के अनुकूल सैंपल संग्रह के क्या विकल्प हैं?",
    faq6A: "हम प्राकृतिक वैवाहिक संबंध के दौरान उपयोग किए जाने वाले गैर-शुक्राणुनाशक छिद्रित सिलिकॉन शीथ का समर्थन करते हैं ताकि सभी धार्मिक मूल्यों का सम्मान हो सके।",

