    tier0DescFull: "तीव्र क्लिनिकल आपातकालीन चेतावनी — गंभीर लक्षण या तीव्र आघात पाया गया। तत्काल विशेषज्ञ हस्तक्षेप और आपातकालीन विभाग मूल्यांकन आवश्यक है।",
    tier1TitleFull: "स्तर 1: यूरोलॉजी एवं एंड्रोलॉजी विशेषज्ञ रेफरल",
    tier1DescFull: "विशेषज्ञ रेफरल आवश्यक है। निष्कर्ष चिकित्सीय रूप से महत्वपूर्ण विकृति (जैसे, स्पर्शनीय वेरिकोसील, गंभीर ऑलिगोज़ूस्पर्मिया या हार्मोनल असंतुलन) का संकेत देते हैं। 2 सप्ताह के भीतर स्क्रोटल डॉपलर अल्ट्रासाउंड और हार्मोनल जांच की सिफारिश की जाती है।",
    tier2TitleFull: "स्तर 2: प्राथमिक चिकित्सा और जीवनशैली अनुकूलन",
    tier2DescFull: "प्राथमिक चिकित्सा हस्तक्षेप और जीवनशैली सुधार की अनुशंसा: अंडकोश के थर्मल तनाव (लैपटॉप हीट) को कम करें, नींद की गुणवत्ता में सुधार (≥7 घंटे), एंटीऑक्सीडेंट युक्त पोषण (CoQ10, जिंक, सेलेनियम) लें, मध्यम व्यायाम 4-5 दिन/सप्ताह करें, तथा 72-90 दिनों के पूर्ण शुक्राणुजनन चक्र के बाद पुनः वीर्य परीक्षण निर्धारित करें।",
    tier3TitleFull: "स्तर 3: दंपत्ति-केंद्रित उप-प्रजनन क्षमता जांच",
    tier3DescFull: "दंपत्ति-केंद्रित उप-प्रजनन क्षमता जांच आवश्यक है। उन्नत वीर्य परीक्षण (डीएनए विखंडन, आरओएस परख), हार्मोनल पैनल समीक्षा और साथी के समानांतर मूल्यांकन के लिए एंड्रोलॉजी विशेषज्ञ को रेफर करें। सांस्कृतिक रूप से संवेदनशील परामर्श पर विचार करें।",
    tier4TitleFull: "स्तर 4: निवारक स्व-देखभाल एवं निगरानी",
    tier4DescFull: "कोई तत्काल चिकित्सीय चिंता नहीं पाई गई। संतुलित पोषण, नियमित शारीरिक गतिविधि, पर्याप्त नींद (7-8 घंटे) और वार्षिक प्रजनन स्वास्थ्य जांच सहित नियमित निवारक प्रथाओं को जारी रखें।",
  
    'dailyPillarChecklistTitle': 'दैनिक 5-स्तंभ देखभाल चेकलिस्ट',
  
