    faq4Q: "كيف يحمي نظام الفرز خماسي المستويات سلامة المريض؟",
    faq4A: "يفصل النظام بدقة بين الفحص الاسترشادي والتشخيص الطبي. الأعراض الحادة توجه المريض للمستشفى فوراً دون تأخير.",
    faq5Q: "كيف تتم الاستشارات الطبية بالفيديو والمكالمات؟",
    faq5A: "يتواصل المرضى مباشرة عبر مكالمات WebRTC مشفرة بالكامل، أو عبر خطوط صوتية أو محادثات واتساب رسمية مع استشاريي الذكورة المعتمدين.",
    faq6Q: "ما هي الخيارات المتاحة لجمع العينات وفق الضوابط الدينية؟",
    faq6A: "ندعم استخدام الأغماد السيليكونية المثقوبة غير القاتلة للنطاف أثناء العلاقة الزوجية الطبيعية، بما يضمن احترام كافة المعتقدات الدينية.",

