    tier0TitleFull: "المستوى 0: تنبيه سريري لحالات الطوارئ الحادة",
    tier0DescFull: "تنبيه طوارئ سريري حاد — تم رصد أعراض شديدة أو صدمة حادة. يلزم التدخل الفوري لأخصائي وتقييم قسم الطوارئ.",
    tier1TitleFull: "المستوى 1: إحالة إلى أخصائي المسالك البولية والذكورة",
    tier1DescFull: "يلزم الإحالة إلى أخصائي. تشير النتائج إلى وجود حالة سريرية مهمة (مثل دوالي الخصية المحسوسة أو قلة النطاف الشديدة). يوصى بإجراء تصوير بالموجات فوق الصوتية دوبلر لكيس الصفن وفحص هرموني في غضون أسبوعين.",
    tier2TitleFull: "المستوى 2: الرعاية الأولية وتحسين نمط الحياة",
    tier2DescFull: "يوصى بتدخلات الرعاية الأولية وتحسين نمط الحياة: تقليل التعرض للحرارة الصفنية، تحسين جودة النوم (≥7 ساعات)، تناول مضادات الأكسدة (CoQ10، الزنك، السيلينيوم)، ممارسة الرياضة 4-5 أيام أسبوعيًا، وتحديد موعد لتحليل السائل المنوي للمتابعة بعد دورة تكوّن الحيوانات المنوية (72-90 يومًا).",
    tier3TitleFull: "المستوى 3: استقصاء نقص الخصوبة المرتكز على الزوجين",
    tier3DescFull: "يوصى بإجراء استقصاء لنقص الخصوبة مرتكز على الزوجين. الإحالة إلى أخصائي الذكورة لإجراء تحليل متقدم للسائل المنوي (تفتت الحمض النووي وفحص ROS) ومراجعة الهرمونات وتقييم موازٍ للزوجة.",
    tier4TitleFull: "المستوى 4: الرعاية الذاتية الوقائية والمتابعة",
    tier4DescFull: "لم يتم تحديد أي قلق سريري فوري. استمر في الممارسات الصحية الوقائية بما في ذلك التغذية المتوازنة والنشاط البدني المنتظم والنوم الكافي (7-8 ساعات) والفحوصات السنوية.",
  
