    faq1Q: "为什么男性生殖健康评估必须以 72 至 90 天为一个周期？",
    faq1A: "人类精子自生精小管干细胞发育至成熟需 64 至 74 天，随后在附睾内获得运动力需 10 至 14 天。因此消除高温、补充辅酶等调理方案必须经过一个完整周期，方能在精液复查中体现出指标提升。",
    faq2Q: "Reprogenix AI 采用的世界卫生组织（WHO）第六版参考标准包含哪些？",
    faq2A: "WHO 精液分析手册第六版（2021）确立了正常生育力男性第5百分位下限：精子浓度 ≥ 16 百万/mL、前向运动力 ≥ 30%、总活力 ≥ 42%、正常形态率 ≥ 4.0%。本系统以此作为国际基准。",
    faq3Q: "Reprogenix AI 如何严格保护用户的敏感生殖隐私数据？",
    faq3A: "我们贯彻零持久化个人数据（Zero Persistent PII）原则。所有筛查与生活习惯评估均在服务器易失性内存（RAM）中运算，会话结束后瞬间释放，绝不写入云端数据库，完全符合 HIPAA 与 GDPR 第9条要求。",
    faq4Q: "安全五级分诊引擎如何确保患者生命安全与就医合规？",
    faq4A: "系统明确区分初步筛查与专科医疗诊断。一旦出现急性睾丸扭转等红线体征，系统即刻触发 0 级急症报警，无条件绕过后续评分，强制提示前往就近急诊科。",
    faq5Q: "远程男科视频与语音问诊是如何开展的？",
    faq5A: "患者可通过端到端加密的 WebRTC 视频会议室、直拨语音通话或官方认证 WhatsApp 专线，与莎拉·约翰逊医生等资深男科专家直接沟通复查与治疗方案。",
    faq6Q: "针对特殊信仰与文化习俗，有哪些非侵入性的样本收集选项？",
    faq6A: "我们支持在自然夫妻生活中使用无杀精剂打孔医用硅胶收集护套等文化友好方式，充分尊重每一位患者的伦理信仰与精神价值观。",

